using System;
using UnityEngine;
namespace Veilbound {
 public partial class VeilGame {
  string CityDescription(string id){switch(id){case "clothier":return "A shared workshop for cloth and hide equipment, from a canvas shelter to a grand guildhall.";case "library":return "Research settlement technology, then construct the upgrades you unlock.";case "herbalist":return "A reserved plot for herbal remedies and alchemy.";case "enchanter":return "Spend Veil Essence to enchant owned equipment. Upgrades add a second enchantment and unlock targeted stats.";case "housing":return "Healthier, growing households improve all passive production by 20% per housing tier.";case "mine":return "Queue ore work orders. Each delivery adds one unit. Mine upgrades shorten the time per unit by increasing mining speed.";case "hunters":return "Gather hides from the surrounding wilds. Choose which grades your hunters bring home.";case "weaver":return "Supply fibres and textiles. Split capacity across the materials your tailors need.";case "timber":return "Harvest timber from the nearby forest to build and improve your settlement.";case "quarry":return "Cut stone for construction and workshop upgrades.";case "blacksmith":return "Refine metal bars and forge weapons and plate. Enchant finished equipment at the Mystic.";case "tailor":return "Craft cloth equipment and capes from your gathered textiles.";default:return "Turn gathered hides into leather equipment. Enchant finished equipment at the Mystic.";}}
  void CityBuildingPortrait(Rect r){int index=Array.IndexOf(CityMapBuildings,cityBuilding);if(index<0)index=Array.IndexOf(CityMapBuildings,cityBuilding=="tailor"?"weaver":"hunters");Vector2 p=CityBuildingPoints[index];Box(r,new Color(.015f,.02f,.021f));DrawTownPortrait(r,cityBuilding);CardOutline(r,new Color(.21f,.22f,.19f));}
  void CityDetails(){Rect r=CityPanelRect;CityFrame(r);string id=cityBuilding;int level=city.BuildingLevel(id),src=CitySource(id);GUI.Label(new Rect(1098,207,456,37),CityBuildingName(id).ToUpper()+" / LEVEL "+level,CityType(25,cityIvory,true));CityBuildingPortrait(new Rect(1404,253,148,87));GUI.Label(new Rect(1098,260,290,76),CityDescription(id),CityType(14,muted));
   if(id=="housing")CityHousingDetails();else if(src>=0)CityProducerOverview(src);
   else if(id=="timber"||id=="quarry")CityConstructionDetails(id);
   else if(id=="clothier"||id=="library"||id=="herbalist"||id=="enchanter")CityServiceDetails(id);else CityWorkshopDetails(id);
   CityUpgradeFooter(id);
  }
  void AdjustCityAllocation(int source,int index,double delta){double current=city.Allocation(source)[index];if(city.Allocate(source,index,current+delta)){Save();notice="Allocation saved.";}}
  void CityAllocateAll(int source,int index){if(city.ProducerLevel(source)<Settlement.ResourceUnlocks[source][index])return;Array.Clear(city.Allocation(source),0,city.Allocation(source).Length);city.Allocate(source,index,city.Capacity(source));Save();notice="All capacity assigned to "+Settlement.ResourceNames[source][index]+".";}
  void CityProductionDetails(int source){double used=city.UsedCapacity(source),cap=city.Capacity(source);Rect summary=new Rect(1098,403,454,54);Box(summary,new Color(.06f,.068f,.064f));CardOutline(summary,new Color(.19f,.21f,.19f));GUI.Label(new Rect(1110,409,420,24),$"CAPACITY ALLOCATED    {used:0.#} / {cap:0.#}",CityType(16,cityIvory,true));GUI.Label(new Rect(1110,435,420,20),"Time per unit uses city time. Expeditions speed up deliveries.",CityType(12,muted));GUI.Label(new Rect(1098,469,230,21),cityDetailTab==0?"MATERIAL / ALLOCATION":"MATERIAL STOCK",CityType(10,muted));GUI.Label(new Rect(1302,469,108,21),"IN STOCK",CityType(10,muted,false,TextAnchor.UpperRight));GUI.Label(new Rect(1430,469,122,21),"TIME / UNIT",CityType(10,muted,false,TextAnchor.UpperRight));
   int length=Settlement.ResourceNames[source].Length,pages=(length+3)/4;cityResourcePage=Mathf.Clamp(cityResourcePage,0,pages-1);
   for(int row=0;row<4;row++){int index=cityResourcePage*4+row;if(index>=length)break;float y=496+row*62;bool unlocked=city.ProducerLevel(source)>=Settlement.ResourceUnlocks[source][index];Color text=unlocked?cityIvory:muted;var icon=MaterialIcon(ResourceIconNames[source][index]);if(icon){GUI.color=unlocked?Color.white:new Color(.45f,.45f,.45f);GUI.DrawTexture(new Rect(1098,y+1,33,33),icon);GUI.color=Color.white;}GUI.Label(new Rect(1140,y+3,163,24),Settlement.ResourceNames[source][index],CityType(14,text));GUI.Label(new Rect(1306,y+3,104,24),Math.Floor(Math.Max(0,city.ResourceAmount(source,index))).ToString("N0"),CityType(15,text,false,TextAnchor.UpperRight));GUI.Label(new Rect(1425,y+3,125,24),unlocked?ProductionTime.PerUnit(city.ProductionRate(source,index)):"Locked",CityType(14,unlocked?new Color(.84f,.68f,.46f):muted,false,TextAnchor.UpperRight));
    if(cityDetailTab==0){double effort=city.Allocation(source)[index];GUI.Label(new Rect(1140,y+32,220,22),unlocked?"Capacity "+effort.ToString("0.#"):"Requires level "+Settlement.ResourceUnlocks[source][index],CityType(11,muted));CityButton(1360,y+29,27,25,"−",()=>AdjustCityAllocation(source,index,-1),unlocked&&effort>=1);GUI.Label(new Rect(1390,y+30,39,23),effort.ToString("0.#"),CityType(13,cityIvory,false,TextAnchor.MiddleCenter));CityButton(1434,y+29,27,25,"+",()=>AdjustCityAllocation(source,index,1),unlocked&&cap-used>=1-1e-9);CityButton(1470,y+29,80,25,"Assign all",()=>CityAllocateAll(source,index),unlocked&&cap>0);}
    else GUI.Label(new Rect(1140,y+33,410,22),unlocked?"1 unit every "+(city.ProductionRate(source,index)>0?ProductionTime.Duration(1/city.ProductionRate(source,index))+" city time":"— assign capacity to start"):"Unlock at level "+Settlement.ResourceUnlocks[source][index],CityType(11,muted));HudLine(new Vector2(1098,y+58),new Vector2(1552,y+58),new Color(.17f,.18f,.16f));
   }
   CityButton(1098,753,66,28,"Previous",()=>cityResourcePage--,cityResourcePage>0);GUI.Label(new Rect(1171,755,80,24),(cityResourcePage+1)+" / "+pages,CityType(12,muted,false,TextAnchor.MiddleCenter));CityButton(1257,753,66,28,"Next",()=>cityResourcePage++,cityResourcePage<pages-1);CityButton(1382,753,170,28,"Clear allocation",()=>{Array.Clear(city.Allocation(source),0,length);Save();},cityDetailTab==0&&used>0);
  }
  void CityConstructionDetails(string id){double rate=id=="timber"?city.WoodRate:city.StoneRate;string material=id=="timber"?"timber":"stone";var icon=MaterialIcon(material);if(icon)GUI.DrawTexture(new Rect(1120,392,66,66),icon);GUI.Label(new Rect(1207,397,322,34),ProductionTime.PerUnit(rate)+" city time",CityType(27,cityIvory,true));GUI.Label(new Rect(1207,435,322,26),"Stock: "+Math.Floor(Math.Max(0,id=="timber"?city.wood:city.stone)).ToString("N0"),CityType(16,muted));GUI.Label(new Rect(1100,500,450,68),"Building materials gather automatically. Upgrade this building to shorten the time per unit.",CityType(17,cityIvory));GUI.Label(new Rect(1100,604,450,76),"Your expedition's production multiplier applies while you are in the Veil. Only active play advances the settlement clock.",CityType(14,muted));}
  void CityWorkshopDetails(string id){bool smith=id=="blacksmith";int family=smith?3:id=="tailor"?1:2;string producer=id=="tailor"?"weaver":"hunters";GUI.Label(new Rect(1100,380,450,30),"WORKSHOP / LEVEL "+city.BuildingLevel(id),CityType(18,cityIvory,true));GUI.Label(new Rect(1100,421,450,68),smith?"Choose a metal to refine bars or forge a weapon. Armour and weapon crafts retain every rolled copy.":"Craft a new piece, compare its stats and equip it in your loadout. Existing pieces stay in your inventory.",CityType(16,muted));
   if(smith){CityButton(1100,520,450,45,"Refine bars & forge weapons",()=>OpenCityWorkshop(false));CityButton(1100,582,450,45,"Craft plate armour",()=>OpenCityWorkshop(true));GUI.Label(new Rect(1100,710,450,60),"Costs increase with material tier.\nPlate and weapons also need finished leather and cloth.",CityType(13,muted));}
   else {CityButton(1100,520,450,45,id=="tailor"?"Craft cloth & capes":"Craft leather armour",()=>{if(gearSlot>8)gearSlot=2;OpenCityWorkshop(true,family);});CityButton(1100,582,450,45,id=="tailor"?"Manage textile supply":"Manage hunting",()=>SelectCityBuilding(producer));GUI.Label(new Rect(1100,710,450,60),"Chest 8 materials · Helm / shoulders / legs 6\nSmaller pieces 4 · Secondary ingredients may apply",CityType(13,muted));}
   CityButton(1100,644,450,45,"View loadout & owned gear",()=>{tab=1;selection=0;});}
  void CityUpgradeFooter(string id){if(city.activeConstruction==id){CityButton(1098,806,180,39,"Cancel & refund",()=>{city.CancelConstruction();Save();});GUI.Label(new Rect(1290,788,264,70),"Constructing level "+city.constructionTarget+" / "+city.constructionRemaining.ToString("0.0")+" city hours left",CityType(12,cityIvory));return;}bool max=CityBuildingMax(id);string requirement=city.ConstructionRequirement(id);CityButton(1098,774,180,26,"Queue build / upgrade",()=>QueueGoal(0,id),!max&&id!="herbalist");CityButton(1098,806,180,39,max?"Fully upgraded":city.BuildingLevel(id)==0?"Build":"Upgrade",()=>Buy(id),!max&&city.CanUpgrade(id));GUI.Label(new Rect(1290,788,264,70),max?"Maximum level reached.":requirement!=""?requirement:city.UpgradeCostText(id),CityType(11,max||city.CanUpgrade(id)?cityIvory:muted));}
 }
}
